/**
 * Bone Cancer Interventional Oncology Assessment Logic
 * Based on NCCN 2026 Guidelines — Principles of Interventional Oncology (BONE-E)
 * Society of Interventional Oncology (SIO)
 */

export type TumorType =
  | "osteosarcoma"
  | "chondrosarcoma"
  | "gctb"
  | "abc"
  | "bone-metastases"
  | "chordoma"
  | "other";

export type ResectabilityStatus = "resectable" | "unresectable" | "relapsed-refractory";

export type TumorLocation =
  | "spine"
  | "pelvis"
  | "femur"
  | "tibia"
  | "humerus"
  | "other-extremity"
  | "other";

export type TreatmentGoal = "curative" | "palliative" | "preoperative";

export type AblationModality = "rfa" | "mwa" | "cryoablation" | "hifu" | "combination";

export type EmbolizationType = "preoperative" | "palliative" | "serial";

export interface PatientData {
  age: number;
  performanceStatus: "0" | "1" | "2" | "3" | "4"; // ECOG
  hasCoagulopathy: boolean;
  coagulopathyCorrectible: boolean;
  activeInfection: boolean;
  medicalComorbidities: string[];
}

export interface TumorData {
  tumorType: TumorType;
  resectabilityStatus: ResectabilityStatus;
  location: TumorLocation;
  sizeInCm: number;
  isPainful: boolean;
  painSeverity?: number; // 0-10 scale
  hasVascularInvolvement: boolean;
  priorTreatments: string[]; // "chemotherapy", "radiation", "surgery", etc.
  diseaseStatus: "primary" | "recurrent" | "oligometastatic" | "polymetastatic";
}

export interface ProcedureConsiderations {
  treatmentGoal: TreatmentGoal;
  proposedAblationModality?: AblationModality;
  proposedEmbolizationType?: EmbolizationType;
  combinationTherapy: string[]; // "augmentation", "embolization", "radiation", etc.
  thermalProtectionNeeded: boolean;
  criticalStructuresNearby: boolean;
}

export interface ContraindicationScreening {
  uncorrectableCoagulopathy: boolean;
  activeInfectionInArea: boolean;
  unprotectableCriticalStructures: boolean;
}

export interface ScoringResult {
  candidacyScore: number; // 0-100
  candidacyLabel: "excellent" | "good" | "fair" | "poor" | "contraindicated";
  recommendedModalities: AblationModality[];
  recommendedApproach?: EmbolizationType;
  expectedOutcomes: {
    technicalSuccessRate: number;
    localControlRate: number;
    painReliefRate?: number;
    complicationRate: number;
  };
  keyConsiderations: string[];
  contraindications: string[];
  warnings: string[];
}

/**
 * Calculate interventional oncology candidacy for bone cancer
 */
export function assessBoneCancerCandidacy(
  patientData: PatientData,
  tumorData: TumorData,
  procedureConsiderations: ProcedureConsiderations,
  contraindications: ContraindicationScreening
): ScoringResult {
  let score = 100;
  const keyConsiderations: string[] = [];
  const contraindictionsList: string[] = [];
  const warnings: string[] = [];
  let candidacyLabel: "excellent" | "good" | "fair" | "poor" | "contraindicated" = "excellent";
  const recommendedModalities: AblationModality[] = [];
  let expectedTechnicalSuccess = 95;
  let expectedLocalControl = 85;
  let expectedPainRelief = 75;
  let expectedComplication = 5;

  // ─────────────────────────────────────────────────────────────────────────────
  // ABSOLUTE CONTRAINDICATIONS
  // ─────────────────────────────────────────────────────────────────────────────

  if (contraindications.uncorrectableCoagulopathy) {
    contraindictionsList.push("Uncorrectable coagulopathy (absolute contraindication)");
    score = 0;
    candidacyLabel = "contraindicated";
  }

  if (contraindications.activeInfectionInArea) {
    contraindictionsList.push("Active infection in planned treatment area (absolute contraindication)");
    score = 0;
    candidacyLabel = "contraindicated";
  }

  if (contraindications.unprotectableCriticalStructures) {
    contraindictionsList.push(
      "Inability to displace or protect adjacent critical structures (relative contraindication)"
    );
    score -= 25;
    warnings.push(
      "Requires detailed risk-benefit discussion and advanced thermal protection strategies"
    );
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // TUMOR CHARACTERISTICS ASSESSMENT
  // ─────────────────────────────────────────────────────────────────────────────

  // Tumor type suitability
  switch (tumorData.tumorType) {
    case "osteosarcoma":
      keyConsiderations.push(
        "Osteosarcoma: RFA is standard for relapsed/refractory disease; cryoablation is safe alternative"
      );
      recommendedModalities.push("rfa", "cryoablation");
      expectedLocalControl = 85;
      break;
    case "chondrosarcoma":
      keyConsiderations.push("Chondrosarcoma: Ablation is treatment option for recurrent disease");
      recommendedModalities.push("rfa", "cryoablation");
      expectedLocalControl = 80;
      break;
    case "gctb":
      keyConsiderations.push(
        "Giant Cell Tumor of Bone (GCTB): Cryoablation has excellent local control (recurrence 2.3%); consider serial embolization with denosumab for large/sacropelvic lesions"
      );
      recommendedModalities.push("cryoablation");
      if (procedureConsiderations.proposedEmbolizationType === "serial") {
        recommendedModalities.push("rfa");
      }
      expectedLocalControl = 97.7; // 2.3% recurrence rate
      break;
    case "abc":
      keyConsiderations.push(
        "Aneurysmal Bone Cyst (ABC): Serial arterial embolization is effective primary treatment, especially for surgically inaccessible locations (spine, pelvis); healing rates 58-83%"
      );
      recommendedModalities.push("rfa");
      procedureConsiderations.proposedEmbolizationType = "serial";
      expectedLocalControl = 70;
      break;
    case "bone-metastases":
      keyConsiderations.push(
        "Bone Metastases: RFA is standard treatment (SPARTA study: 100% technical success); excellent for pain palliation (60-80% pain control)"
      );
      recommendedModalities.push("rfa", "mwa");
      if (tumorData.isPainful) {
        expectedPainRelief = 75;
      }
      expectedLocalControl = 85;
      break;
    case "chordoma":
      keyConsiderations.push("Chordoma: Ablation is treatment option for recurrent disease");
      recommendedModalities.push("rfa", "cryoablation");
      expectedLocalControl = 80;
      break;
    default:
      recommendedModalities.push("rfa", "mwa", "cryoablation");
  }

  // Resectability assessment
  if (tumorData.resectabilityStatus === "unresectable") {
    keyConsiderations.push(
      "Unresectable tumor: Image-guided ablation is appropriate treatment option"
    );
    score += 15;
  } else if (tumorData.resectabilityStatus === "relapsed-refractory") {
    keyConsiderations.push(
      "Relapsed/refractory disease: Ablation is indicated when excision is not possible"
    );
    score += 10;
  } else if (tumorData.resectabilityStatus === "resectable") {
    if (procedureConsiderations.treatmentGoal === "preoperative") {
      keyConsiderations.push(
        "Preoperative embolization: Reduces intraoperative blood loss and facilitates tumor resection (perform 24-48 hours prior to surgery)"
      );
      procedureConsiderations.proposedEmbolizationType = "preoperative";
    }
  }

  // Tumor location considerations
  if (tumorData.location === "spine" || tumorData.location === "pelvis") {
    keyConsiderations.push(
      "Spine/Pelvis location: Anatomically challenging; embolization particularly beneficial to reduce blood loss; thermal protection critical"
    );
    procedureConsiderations.thermalProtectionNeeded = true;
    score += 5;
  }

  // Size assessment
  if (tumorData.sizeInCm > 5) {
    warnings.push("Large tumor (>5 cm): May require staged ablation or combination approach");
    score -= 10;
  }

  // Pain assessment
  if (tumorData.isPainful && tumorData.painSeverity && tumorData.painSeverity >= 7) {
    keyConsiderations.push(
      "Severe pain: Palliative ablation can achieve pain control in 60-80% of patients with rapid response (median 1-2 days)"
    );
    procedureConsiderations.treatmentGoal = "palliative";
    score += 10;
  }

  // Vascular involvement
  if (tumorData.hasVascularInvolvement) {
    keyConsiderations.push("Hypervascular tumor: Preoperative embolization reduces blood loss");
    procedureConsiderations.proposedEmbolizationType = "preoperative";
    score += 5;
  }

  // Prior treatments
  if (tumorData.priorTreatments.includes("chemotherapy") && tumorData.priorTreatments.includes("radiation")) {
    keyConsiderations.push(
      "Disease progression despite conventional therapies: Candidate for interventional oncology approach"
    );
    score += 5;
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // PATIENT FACTORS ASSESSMENT
  // ─────────────────────────────────────────────────────────────────────────────

  if (patientData.performanceStatus === "3" || patientData.performanceStatus === "4") {
    warnings.push("Poor performance status: Multidisciplinary team discussion strongly recommended");
    score -= 15;
  }

  if (patientData.hasCoagulopathy && !patientData.coagulopathyCorrectible) {
    contraindictionsList.push("Uncorrectable coagulopathy");
    score = 0;
    candidacyLabel = "contraindicated";
  }

  if (patientData.activeInfection) {
    contraindictionsList.push("Active infection");
    score = 0;
    candidacyLabel = "contraindicated";
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // PROCEDURE-SPECIFIC CONSIDERATIONS
  // ─────────────────────────────────────────────────────────────────────────────

  if (procedureConsiderations.combinationTherapy.includes("augmentation")) {
    keyConsiderations.push(
      "Combination ablation + cement augmentation/osteoplasty: Recommended for osseous destruction or increased fracture risk, especially weight-bearing bones"
    );
  }

  if (procedureConsiderations.combinationTherapy.includes("radiation")) {
    keyConsiderations.push(
      "Ablation + radiation therapy: May produce faster and longer-lasting pain relief than radiation alone"
    );
  }

  if (procedureConsiderations.thermalProtectionNeeded) {
    keyConsiderations.push(
      "Thermal protection strategies required: Hydrodissection, pneumodissection, temperature monitoring to minimize risk of thermal injury to adjacent structures"
    );
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // MODALITY-SPECIFIC OUTCOMES
  // ─────────────────────────────────────────────────────────────────────────────

  if (procedureConsiderations.proposedAblationModality === "cryoablation") {
    expectedComplication = 2.5; // Cryoablation complication rate ~2.5%, secondary fracture most common
    keyConsiderations.push("Cryoablation complication rate: ~2.5% (secondary fracture most common)");
  }

  if (procedureConsiderations.proposedAblationModality === "rfa") {
    keyConsiderations.push(
      "RFA: Standard treatment for osteoid osteoma and bone metastases; higher technical success and lower morbidity compared to open surgery"
    );
  }

  if (procedureConsiderations.proposedEmbolizationType === "serial") {
    expectedLocalControl = 75;
    keyConsiderations.push(
      "Serial embolization: Preferred approach for GCTB, especially when combined with denosumab for synergistic sclerosis and pain reduction"
    );
  }

  if (procedureConsiderations.proposedEmbolizationType === "preoperative") {
    keyConsiderations.push(
      "Preoperative embolization: Ideally performed 24-48 hours prior to surgery; reduces intraoperative blood loss and facilitates tumor resection"
    );
  }

  if (procedureConsiderations.proposedEmbolizationType === "palliative") {
    expectedPainRelief = 70;
    keyConsiderations.push(
      "Palliative embolization: Achieves pain control in 60-80% of patients with painful bone metastases; median response time 1-2 days"
    );
  }

  // ─────────────────────────────────────────────────────────────────────────────
  // FINAL SCORE NORMALIZATION & LABEL ASSIGNMENT
  // ─────────────────────────────────────────────────────────────────────────────

  // Ensure score is within bounds
  score = Math.max(0, Math.min(100, score));

  if (candidacyLabel !== "contraindicated") {
    if (score >= 85) {
      candidacyLabel = "excellent";
    } else if (score >= 70) {
      candidacyLabel = "good";
    } else if (score >= 50) {
      candidacyLabel = "fair";
    } else {
      candidacyLabel = "poor";
    }
  }

  return {
    candidacyScore: score,
    candidacyLabel,
    recommendedModalities: recommendedModalities.length > 0 ? recommendedModalities : ["rfa"],
    recommendedApproach: procedureConsiderations.proposedEmbolizationType,
    expectedOutcomes: {
      technicalSuccessRate: expectedTechnicalSuccess,
      localControlRate: expectedLocalControl,
      painReliefRate: tumorData.isPainful ? expectedPainRelief : undefined,
      complicationRate: expectedComplication,
    },
    keyConsiderations,
    contraindications: contraindictionsList,
    warnings,
  };
}

/**
 * Generate clinical summary for bone cancer assessment
 */
export function generateBoneCancerSummary(result: ScoringResult): string {
  const modalities = result.recommendedModalities.join(", ").toUpperCase();
  const approach = result.recommendedApproach
    ? ` using ${result.recommendedApproach.replace("-", " ")} approach`
    : "";

  let summary = `**Candidacy: ${result.candidacyLabel.toUpperCase()}** (Score: ${result.candidacyScore}/100)\n\n`;

  if (result.contraindications.length > 0) {
    summary += `**Contraindications:**\n${result.contraindications.map((c) => `- ${c}`).join("\n")}\n\n`;
  }

  summary += `**Recommended Modalities:** ${modalities}${approach}\n\n`;

  summary += `**Expected Outcomes:**\n`;
  summary += `- Technical Success: ${result.expectedOutcomes.technicalSuccessRate}%\n`;
  summary += `- Local Control: ${result.expectedOutcomes.localControlRate}%\n`;
  if (result.expectedOutcomes.painReliefRate) {
    summary += `- Pain Relief: ${result.expectedOutcomes.painReliefRate}%\n`;
  }
  summary += `- Complication Rate: ${result.expectedOutcomes.complicationRate}%\n\n`;

  if (result.keyConsiderations.length > 0) {
    summary += `**Key Considerations:**\n${result.keyConsiderations.map((c) => `- ${c}`).join("\n")}\n\n`;
  }

  if (result.warnings.length > 0) {
    summary += `**Warnings:**\n${result.warnings.map((w) => `- ${w}`).join("\n")}\n`;
  }

  return summary;
}
